    t = len(hist) - 1
    last_close = float(close[-1])

    atr14 = ind.atr(hist, 14)
    atr = float(atr14[-1]) if len(atr14) else float("nan")

    box_n = 32
    if len(close) < box_n + 1:
        return {"target": pos, "stop": None, "take": None}

    prev_box_high = float(np.max(high[-(box_n + 1):-1]))
    prev_box_low = float(np.min(low[-(box_n + 1):-1]))
    box_height = prev_box_high - prev_box_low

    in_trade = "side" in state
    if in_trade and state.get("side", 0) == 1:
        entry_price = float(state.get("entry_price", 0.0))
        entry_atr = float(state.get("entry_atr", atr if math.isfinite(atr) else 0.0))
        anchor = float(state.get("anchor", entry_price))
        adds = int(state.get("adds", 0))

        if not math.isfinite(entry_atr) or entry_atr <= 0:
            entry_atr = atr if math.isfinite(atr) and atr > 0 else 0.0

        # Ratchet the whole box forward by 2 ATR every time close is >= 2 ATR past the anchor.
        if entry_atr > 0 and math.isfinite(last_close):
            moved = int((last_close - anchor) // (2.0 * entry_atr))
            if moved > 0:
                anchor += 2.0 * entry_atr * moved
                state["anchor"] = anchor

        # Add another quarter every time price is at least 1 entry ATR in favor from the last add.
        target_frac = 0.0
        if pos > 0:
            target_frac = pos
        elif state.get("desired", 0.0) > 0:
            target_frac = float(state.get("desired", 0.0))
        else:
            target_frac = 0.25

        while entry_atr > 0 and adds < 2:
            last_add = float(state.get("last_add_price", entry_price))
            if last_close >= last_add + entry_atr:
                adds += 1
                state["adds"] = adds
                state["last_add_price"] = last_add + entry_atr
                target_frac = min(1.0, 0.25 * (1 + adds))
            else:
                break

        # Dynamic box: stop 1 ATR behind anchor, take 2 ATR ahead.
        stop = anchor - entry_atr if entry_atr > 0 else None
        take = anchor + 2.0 * entry_atr if entry_atr > 0 else None

        # If a short signal appears, flatten; shorting is not used.
        if len(close) >= 2 and float(close[-1]) < float(close[-2]) and pos > 0 and float(close[-1]) < prev_box_low:
            state["exit_pending"] = True
            return {"target": 0.0, "stop": stop, "take": take}

        state["desired"] = target_frac
        return {"target": target_frac, "stop": stop, "take": take}

    # Flat: only long breakout if box height <= 3 ATR and close above the top.
    if not math.isfinite(atr) or atr <= 0:
        return {"target": pos, "stop": None, "take": None}

    if box_height <= 3.0 * atr and last_close > prev_box_high:
        state["side"] = 1
        state["entry_price"] = last_close
        state["entry_atr"] = atr
        state["anchor"] = last_close
        state["adds"] = 0
        state["last_add_price"] = last_close
        state["desired"] = 0.25
        state["exit_pending"] = False
        return {"target": 0.25, "stop": last_close - atr, "take": last_close + 2.0 * atr}

    # Short signals just get us flat.
    if len(close) >= 2 and last_close < float(close[-2]) and pos > 0:
        return {"target": 0.0, "stop": None, "take": None}

    return {"target": pos, "stop": None, "take": None}

