    high = hist.high
    low = hist.low

    n = len(hist)
    if n < 50:
        return {"target": pos, "stop": None, "take": None}

    t = n - 1

    atr14 = ind.atr(hist, 14)
    atr = float(atr14[-1])
    c = float(close[-1])

    # State init / cleanup
    if "cooldown_until" not in state:
        state["cooldown_until"] = -1
    if "entry_atr" not in state:
        state["entry_atr"] = 0.0
    if "base_anchor" not in state:
        state["base_anchor"] = 0.0
    if "box_rungs" not in state:
        state["box_rungs"] = 0
    if "last_pos" not in state:
        state["last_pos"] = float(pos)

    # Detect position transitions to start cooldown after any exit
    last_pos = float(state.get("last_pos", pos))
    cur_pos = float(pos)
    if last_pos != 0.0 and cur_pos == 0.0:
        state["cooldown_until"] = t + 16
        state["entry_atr"] = 0.0
        state["base_anchor"] = 0.0
        state["box_rungs"] = 0

    state["last_pos"] = cur_pos

    # If flat, manage entries
    if cur_pos == 0.0:
        if t <= int(state["cooldown_until"]):
            return {"target": 0.0, "stop": None, "take": None}

        box_high = float(ind.highest(high[:-1], 48)[-1]) if n > 48 else float("nan")
        box_low = float(ind.lowest(low[:-1], 48)[-1]) if n > 48 else float("nan")

        long_sig = (not math.isnan(box_high)) and (c > box_high)
        short_sig = (not math.isnan(box_low)) and (c < box_low)

        if long_sig or short_sig:
            risk_frac = 0.01
            k_atr = 2.0
            if not math.isnan(atr) and atr > 0:
                target = risk_frac * c / (k_atr * atr)
            else:
                target = 0.05
            target = max(0.05, min(1.0, target))
            target = round(target / 0.05) * 0.05
            if long_sig:
                return {"target": float(target), "stop": None, "take": None}
            else:
                return {"target": float(-target), "stop": None, "take": None}

        return {"target": 0.0, "stop": None, "take": None}

    # Manage live trade
    side = 1.0 if cur_pos > 0 else -1.0

    # Initialize entry ATR / anchor on first bar after position exists
    if state["entry_atr"] <= 0.0:
        state["entry_atr"] = float(atr) if (not math.isnan(atr) and atr > 0) else 0.0
    if state["base_anchor"] == 0.0:
        state["base_anchor"] = c
        state["box_rungs"] = 0

    entry_atr = float(state["entry_atr"])
    anchor = float(state["base_anchor"])
    rungs = int(state["box_rungs"])

    # Ratchet the box every additional 1 ATR in profit past the anchor
    if entry_atr > 0.0:
        if side > 0:
            profit_steps = int(math.floor((c - anchor) / entry_atr))
            if profit_steps > rungs:
                rungs = profit_steps
        else:
            profit_steps = int(math.floor((anchor - c) / entry_atr))
            if profit_steps > rungs:
                rungs = profit_steps
        state["box_rungs"] = rungs

    # Donchian box base = 48-bar breakout level, ratcheted by 1 ATR per rung
    box_high = float(ind.highest(high[:-1], 48)[-1]) if n > 48 else float("nan")
    box_low = float(ind.lowest(low[:-1], 48)[-1]) if n > 48 else float("nan")

    stop = None
    take = None

    if side > 0:
        if not math.isnan(box_low):
            stop_base = box_low
            if entry_atr > 0.0:
                stop_base = max(stop_base, anchor + (rungs * entry_atr) - 2.0 * entry_atr)
            stop = float(stop_base)
        if not math.isnan(box_high):
            take_base = box_high
            if entry_atr > 0.0:
                take_base = max(take_base, anchor + (rungs * entry_atr) + 2.0 * entry_atr)
            take = float(take_base)

        # Opposite signal closes the open trade
        if (not math.isnan(box_low)) and (c < box_low):
            state["cooldown_until"] = t + 16
            return {"target": 0.0, "stop": None, "take": None}

    else:
        if not math.isnan(box_high):
            stop_base = box_high
            if entry_atr > 0.0:
                stop_base = min(stop_base, anchor - (rungs * entry_atr) + 2.0 * entry_atr)
            stop = float(stop_base)
        if not math.isnan(box_low):
            take_base = box_low
            if entry_atr > 0.0:
                take_base = min(take_base, anchor - (rungs * entry_atr) - 2.0 * entry_atr)
            take = float(take_base)

        # Opposite signal closes the open trade
        if (not math.isnan(box_high)) and (c > box_high):
            state["cooldown_until"] = t + 16
            return {"target": 0.0, "stop": None, "take": None}

    return {"target": float(cur_pos), "stop": stop, "take": take}

