    low = hist.low
    t = hist.time

    n = len(hist)
    if n < 1000:
        return {"target": pos, "stop": None, "take": None}

    atr14 = ind.atr(hist, 14)
    atr = float(atr14[-1])
    c = float(close[-1])

    htf4 = hist.htf(240)
    c4 = htf4.close
    ema20_4h = ind.ema(c4, 20)
    c4v = float(c4[-1])
    ema4v = float(ema20_4h[-1])

    # UTC day tracking
    day = int(t[-1] // 86400000)
    last_day = int(state.get("day", -1))
    if day != last_day:
        state["day"] = day
        state["traded"] = 0

    traded = int(state.get("traded", 0))

    # Channel on the prior 96 bars BEFORE current bar
    if n >= 97:
        prior_high = float(np.max(high[-97:-1]))
        prior_low = float(np.min(low[-97:-1]))
    else:
        prior_high = float("nan")
        prior_low = float("nan")

    long_sig = n >= 97 and c > prior_high and c4v > ema4v
    short_sig = n >= 97 and c < prior_low and c4v < ema4v

    # Manage open trade
    if pos != 0.0:
        entry_price = float(state.get("entry_price", c))
        entry_atr = float(state.get("entry_atr", atr if atr > 0 else 0.0))
        scale_done = bool(state.get("scaled_out", False))

        if pos > 0:
            stop = entry_price - 2.0 * entry_atr
            take = None
            if (not scale_done) and c >= entry_price + 3.0 * entry_atr:
                take = entry_price + 3.0 * entry_atr
            if short_sig:
                state["exit_pending"] = 1
                return {"target": 0.0, "stop": None, "take": None}
            if not scale_done and c >= entry_price + 3.0 * entry_atr:
                state["scaled_out"] = True
                return {"target": 0.5, "stop": stop, "take": None}
            return {"target": pos, "stop": stop, "take": None}

        if pos < 0:
            stop = entry_price + 2.0 * entry_atr
            take = None
            if (not scale_done) and c <= entry_price - 3.0 * entry_atr:
                take = entry_price - 3.0 * entry_atr
            if long_sig:
                state["exit_pending"] = 1
                return {"target": 0.0, "stop": None, "take": None}
            if not scale_done and c <= entry_price - 3.0 * entry_atr:
                state["scaled_out"] = True
                return {"target": -0.5, "stop": stop, "take": None}
            return {"target": pos, "stop": stop, "take": None}

    # Flat: entries, max one per UTC day
    if traded >= 1:
        return {"target": 0.0, "stop": None, "take": None}

    if atr > 0 and not math.isnan(atr):
        raw_size = 0.01 * c / atr
        size = max(0.05, min(1.0, raw_size))
        size = round(size / 0.05) * 0.05
        size = max(0.05, min(1.0, size))
    else:
        size = 0.05

    if long_sig:
        state["traded"] = traded + 1
        state["entry_price"] = c
        state["entry_atr"] = atr
        state["scaled_out"] = False
        state["dir"] = 1
        return {"target": size, "stop": c - 2.0 * atr, "take": None}

    if short_sig:
        state["traded"] = traded + 1
        state["entry_price"] = c
        state["entry_atr"] = atr
        state["scaled_out"] = False
        state["dir"] = -1
        return {"target": -size, "stop": c + 2.0 * atr, "take": None}

    return {"target": 0.0, "stop": None, "take": None}

