def strategy(hist, state, pos, ind) -> dict:
    close = hist.close
    high = hist.high
    low = hist.low

    n = len(hist)
    if n < 65:
        return {"target": pos, "stop": None, "take": None}

    atr14 = ind.atr(hist, 14)
    atr = float(atr14[-1])
    if not np.isfinite(atr) or atr <= 0:
        return {"target": pos, "stop": None, "take": None}

    top = float(ind.highest(high[:-1], 64)[-1])
    bottom = float(ind.lowest(low[:-1], 64)[-1])
    box_height = top - bottom

    if not np.isfinite(box_height) or box_height <= 0 or box_height > 4.0 * atr:
        if pos != 0.0:
            return {"target": 0.0, "stop": None, "take": None}
        return {"target": pos, "stop": None, "take": None}

    c = float(close[-1])

    if pos == 0.0:
        long_sig = c > top
        short_sig = c < bottom
        if long_sig or short_sig:
            raw = 0.0025 * c / atr
            tgt = min(1.0, max(0.05, raw))
            if short_sig:
                tgt = -tgt
            stop = c - 1.5 * atr if long_sig else c + 1.5 * atr
            state["entry_price"] = c
            state["entry_atr"] = atr
            state["scaled"] = False
            state["dir"] = 1 if long_sig else -1
            return {"target": tgt, "stop": stop, "take": None}
        return {"target": pos, "stop": None, "take": None}

    entry_price = float(state.get("entry_price", c))
    entry_atr = float(state.get("entry_atr", atr))
    scaled = bool(state.get("scaled", False))
    direction = 1 if pos > 0 else -1

    stop = entry_price - 1.5 * entry_atr if direction > 0 else entry_price + 1.5 * entry_atr
    take = None

    if not scaled and ((direction > 0 and c >= entry_price + 3.0 * entry_atr) or (direction < 0 and c <= entry_price - 3.0 * entry_atr)):
        state["scaled"] = True
        return {"target": pos * 0.5, "stop": stop, "take": None}

    if direction > 0:
        if c < bottom:
            del state["entry_price"]
            del state["entry_atr"]
            del state["scaled"]
            del state["dir"]
            return {"target": 0.0, "stop": None, "take": None}
    else:
        if c > top:
            del state["entry_price"]
            del state["entry_atr"]
            del state["scaled"]
            del state["dir"]
            return {"target": 0.0, "stop": None, "take": None}

    return {"target": pos, "stop": stop, "take": take}
